'use strict';

// Conformance verification support: statically verify the todo-list reconcile never
// removes a list element that is not a current child of the list.
//
// happy-dom never throws on removeChild of a detached node, so this defect cannot be
// reproduced as a runtime assertion in the harness. The Captain pinned it as a
// @conformance source check instead: the reconcile (in js/app.js) must guard every
// `todoList.removeChild(child)` with a current-child check (todoList.contains(child),
// child.isConnected, or child.parentNode === todoList) so a re-entrant edit-commit path
// cannot call removeChild on a node already detached from the list.
//
// The checker reads js/app.js as source and asserts the structural property. It is owned
// verification support under QM, not a Captain-owned scantling file: it asserts real
// structure (the source's guard), not a spied call.

function matchBracePair(src, openIdx) {
  let depth = 0;
  for (let i = openIdx; i < src.length; i++) {
    const ch = src[i];
    if (ch === '{') depth++;
    else if (ch === '}') {
      if (--depth === 0) return i;
    }
  }
  return -1;
}

function findListVar(source) {
  const m = /const\s+(\w+)\s*=\s*\$\(\s*'\.todo-list'\s*\)/.exec(source);
  return m ? m[1] : null;
}

function extractReconcile(source) {
  const m = /(?:const|function)\s+render\s*=\s*\(\)\s*=>\s*\{/.exec(source);
  if (!m) return source;
  const open = source.indexOf('{', m.index);
  const close = matchBracePair(source, open);
  if (close === -1) return source;
  return source.slice(open, close + 1);
}

function enclosingIfCondition(body, pos) {
  let best = null;
  const re = /if\s*\(/g;
  let m;
  while ((m = re.exec(body))) {
    const condStart = m.index + m[0].length;
    let depth = 0;
    let condEnd = -1;
    for (let i = condStart; i < body.length; i++) {
      const c = body[i];
      if (c === '(') depth++;
      else if (c === ')') {
        if (depth === 0) { condEnd = i; break; }
        depth--;
      }
    }
    if (condEnd === -1) continue;
    const blockStart = body.indexOf('{', condEnd);
    if (blockStart === -1) continue;
    const blockEnd = matchBracePair(body, blockStart);
    if (blockEnd === -1) continue;
    if (pos > blockStart && pos < blockEnd) {
      const len = blockEnd - blockStart;
      if (!best || len < best.len) best = { len, cond: body.slice(condStart, condEnd) };
    }
  }
  return best ? best.cond : null;
}

function hasCurrentChildGuard(cond, listVar, childArg) {
  if (!cond) return false;
  const guards = [
    new RegExp(`\\b${listVar}\\.contains\\(\\s*${childArg}\\s*\\)`),
    new RegExp(`\\b${childArg}\\.isConnected\\b`),
    new RegExp(`\\b${childArg}\\.parentNode\\s*===?\\s*${listVar}\\b`),
  ];
  return guards.some((r) => r.test(cond));
}

function checkReconcile(source) {
  const listVar = findListVar(source);
  if (!listVar) {
    return { ok: false, reason: "could not locate the todo-list element reference ($('.todo-list'))" };
  }
  const reconcile = extractReconcile(source);
  const re = new RegExp(`\\b${listVar}\\.removeChild\\(\\s*([^)]*)\\)`, 'g');
  let m;
  const offenders = [];
  while ((m = re.exec(reconcile))) {
    const childArg = m[1].trim();
    const cond = enclosingIfCondition(reconcile, m.index);
    if (!hasCurrentChildGuard(cond, listVar, childArg)) {
      offenders.push({ childArg, cond: cond || 'none' });
    }
  }
  if (offenders.length === 0) {
    return { ok: true, reason: 'reconcile removes only current children of the todo list (or removes nothing)' };
  }
  const detail = offenders
    .map((o) => `${listVar}.removeChild(${o.childArg}) is not guarded by a current-child check (enclosing condition: ${o.cond})`)
    .join('; ');
  return {
    ok: false,
    reason:
      `reconcile can remove a list element that is not a current child: ${detail}. ` +
      'A re-entrant edit-commit (keydown Enter followed by the focusout a real browser fires on the ' +
      'removed edit input) can call removeChild on a node already detached from the list, raising ' +
      'NotFoundError in a real browser.',
  };
}

module.exports = { checkReconcile };

